 window.IGCSE_ENGLISH_VOCAB_INFO={code:'0510/0511',edition:'2027–2029',scope:'original-skill-and-topic-vocabulary',sourceUrl:'https://help.cambridgeinternational.org/hc/en-gb/articles/28783145916690-What-grammatical-structures-and-vocabulary-are-expected-Is-there-a-list',note:'本站按技能章节和常见主题编排；官方未发布封闭的词汇与语法清单，词库仍可随教材扩充。'};
 for(const section of [{"subject":"business","groups":[{"title":"商业专业术语","items":[{"formula":"Stakeholder · 利益相关者","note":"影响企业或受企业影响的人或群体，如员工、顾客、股东与当地社区。答题要区分不同群体的目标。"},{"formula":"Added value · 附加值","note":"销售价值减去购入原材料/部件成本；与利润不同，尚未扣除所有经营成本。"},{"formula":"Revenue · 收入","note":"单位售价 × 销量。收入不等于利润，也不等于当期收到的现金。"},{"formula":"Profit · 利润","note":"总收入 − 总成本。现金流描述现金收付的时间，二者不能混用。"},{"formula":"Break-even · 盈亏平衡","note":"总收入等于总成本。盈亏平衡产量 = 固定成本 ÷ 单位贡献；单位贡献 = 售价 − 单位变动成本。"},{"formula":"Opportunity cost · 机会成本","note":"选择某方案时放弃的最佳替代方案的价值。"}]},{"title":"市场、财务与运营","items":[{"formula":"Market segmentation · 市场细分","note":"按顾客特征或需求划分市场，以便设计合适的营销组合。"},{"formula":"Cash flow · 现金流","note":"现金流入与流出。期末现金 = 期初现金 + 净现金流。"},{"formula":"Liquidity · 流动性","note":"企业偿还短期债务的能力；销售增长并不保证流动性改善。"},{"formula":"Productivity · 生产率","note":"产出与投入的比率，如每名员工产量；与总产量不同。"},{"formula":"Economies of scale · 规模经济","note":"经营规模扩大导致平均单位成本下降的因素。"},{"formula":"Justify · 论证","note":"给出选择，并用具体情境的证据说明为什么优于替代方案。"}]}]},{"subject":"computer_science","groups":[{"title":"数据与网络术语","items":[{"formula":"Bit / Byte · 位 / 字节","note":"bit 是二进制位；1 byte = 8 bits。容量单位按题目说明使用十进制或二进制倍数。"},{"formula":"Protocol · 协议","note":"设备通信遵循的规则；例如 HTTP 处理网页请求，HTTPS 提供加密保护。"},{"formula":"IP / MAC address","note":"IP 地址用于网络寻址；MAC 地址标识网络接口。不要把两者当作同一层级的地址。"},{"formula":"Encryption · 加密","note":"用算法和密钥把数据转换为不可直接理解的形式，授权方可解密。"},{"formula":"Validation / Verification","note":"Validation 检查输入是否满足规则；verification 检查数据是否被正确复制或输入。合法范围内的输入仍可能错误。"},{"formula":"Primary / Foreign key","note":"主键唯一标识记录；外键关联另一表的键。用于建立关系与维护参照完整性。"}]},{"title":"算法与程序设计","items":[{"formula":"Sequence / Selection / Iteration","note":"顺序、选择、循环是基本控制结构。应结合给定输入追踪程序流程。"},{"formula":"Variable / Constant","note":"变量的值可改变；常量在程序运行过程中保持不变。"},{"formula":"Array · 数组","note":"用共同名称和下标访问一组同类型元素。注意下标边界与初始化。"},{"formula":"Parameter · 参数","note":"向过程或函数传递的数据；局部变量与参数的作用域要分别考虑。"},{"formula":"Trace table · 跟踪表","note":"逐步记录变量值和输出，用来检验算法，不要跳过循环条件检查。"},{"formula":"Testing · 测试数据","note":"正常、异常与边界数据检验不同情况；边界测试要包含临界值及其邻近值。"}]}]},{"subject":"english","groups":[{"title":"英语语法速查","items":[{"formula":"Past simple / Present perfect","note":"Past simple 常用于已结束的过去时间：I visited last week. Present perfect 连接过去与现在：I have visited twice. 明确的已结束时间通常不用现在完成时。"},{"formula":"Subject–verb agreement","note":"单数主语通常搭配单数动词：She works. 注意真正的主语，不能只看离动词最近的名词。"},{"formula":"Articles · 冠词","note":"a/an 指一个非特指的可数名词；the 用于语境中可识别的对象。不可数名词不直接搭配 a/an。"},{"formula":"Conditionals · 条件句","note":"真实将来：If it rains, we will stay. 假设现在：If I had time, I would help. 过去假设：If I had known, I would have helped."},{"formula":"Passive voice · 被动语态","note":"be + 过去分词，be 的时态随语境改变：The report was written yesterday. 适用于强调动作对象或执行者不重要的情况。"},{"formula":"Relative clauses · 定语从句","note":"who 常指人，which 常指物，that 可用于限定性从句。非限定性从句通常用逗号隔开，不能用 that。"}]},{"title":"写作与阅读专业术语","items":[{"formula":"Register · 语体","note":"根据目的和受众选择正式或非正式表达；写给朋友与写正式报告的语气不同。"},{"formula":"Coherence / Cohesion","note":"Coherence 是思想组织和逻辑连贯；cohesion 是代词、连接词等语言衔接。堆积连接词并不能代替清晰逻辑。"},{"formula":"Inference / Evidence","note":"Inference 是从文章线索推断；evidence 是支持推断的具体内容。推断须由文本支持，不能加入无根据的个人猜测。"},{"formula":"Purpose / Audience","note":"先明确为什么写、写给谁，再选择内容、语气与组织方式。"},{"formula":"Paragraph / Topic sentence","note":"段落围绕一个主要意思展开，主题句、说明与例子共同支撑该意思。"},{"formula":"Proofreading · 校对","note":"检查任务覆盖、时态、主谓一致、句界、拼写与标点；使用提示后再独立修改。"}]}]}]){const old=window.IGCSE_QUICKREF.find(s=>s.subject===section.subject);if(old)old.groups.push(...section.groups);else window.IGCSE_QUICKREF.push(section);}
